//! Text: metrics, wrapping and coverage sampling.
//!
//! The font is a committed bitmap (`font_data.zig`, generated once by
//! `tools/gen_font.py` and *not* regenerated by the build): 95 ASCII glyphs at a
//! master size of 14 px, one byte of coverage per pixel. Drawing scales that
//! coverage with a bilinear sample, which is why text stays readable from 10 px
//! to 40 px without shipping a font engine, a hinting pass or a shaping library.
//!
//! Two properties are worth stating because the rest of the library leans on
//! them:
//!
//! * **measure and draw use the same code path.** `measure` walks the same
//!   advances the renderer uses, so a layout can never disagree with the pixels.
//! * **nothing here allocates except `wrap`**, which fills a slice the caller
//!   owns (the frame arena). Measuring is O(glyphs) with no allocation at all.
const std = @import("std");
const data = @import("font_data.zig");

pub const Glyph = data.Glyph;
pub const em = data.em;
pub const ascent = data.ascent;
pub const descent = data.descent;
pub const line_height_at_em = data.ascent + data.descent;

pub const first_char = 32;
pub const last_char = 126;

pub const Metrics = struct {
    /// Sum of the advances: what the line occupies when drawn.
    width: f32 = 0,
    /// Distance from the top of the line box to the baseline.
    ascent: f32,
    /// Distance from the baseline to the bottom of the line box (`> 0`).
    descent: f32,
    height: f32,

    /// Top of the line box for a baseline at `y`.
    pub fn lineTop(self: Metrics, baseline: f32) f32 {
        return baseline - self.ascent;
    }
};

/// Scale factor from the master size to `size`.
pub fn scaleOf(size: f32) f32 {
    return size / em;
}

/// How many bytes the character starting at `text[i]` occupies. The font has no
/// non-ASCII glyphs, but the input layer does not care what the host typed: a
/// multi-byte character is measured and drawn as a single replacement glyph
/// rather than as one '?' per byte, and `\n` is layout rather than ink.
pub fn byteLen(text: []const u8, i: usize) usize {
    const c = text[i];
    if (c < 0x80) return 1;
    const n: usize = if (c >= 0xf0) 4 else if (c >= 0xe0) 3 else if (c >= 0xc0) 2 else 1;
    return @min(n, text.len - i);
}

/// Metrics of a single line of `text` drawn at `size` pixels.
pub fn measure(text: []const u8, size: f32) Metrics {
    const s = scaleOf(size);
    var width: f32 = 0;
    var i: usize = 0;
    while (i < text.len) {
        if (text[i] != '\n') width += advance(text[i], s);
        i += byteLen(text, i);
    }
    return .{
        .width = width,
        .ascent = ascent * s,
        .descent = descent * s,
        .height = line_height_at_em * s,
    };
}

/// Advance of one character (any byte outside ASCII is the replacement glyph).
pub fn advance(c: u8, s: f32) f32 {
    const g = glyphOf(c);
    return g.advance * s;
}

pub fn glyphOf(c: u8) data.Glyph {
    const idx: usize = if (c < first_char or c > last_char) '?' - first_char else c - first_char;
    return data.glyphs[idx];
}

/// Widths used to lay a line out. `x` is the pen position of the glyph's
/// origin, which is *not* the ink's left edge: `bearings` gives that.
pub const GlyphPlacement = struct {
    c: u8,
    x: f32,
    glyph: data.Glyph,
};

/// Walks `text` and reports where each glyph's pen origin lands. Iterating this
/// is what both measuring and drawing do, so they cannot drift apart.
pub fn layout(text: []const u8, size: f32, start: f32) GlyphIterator {
    return .{ .text = text, .s = scaleOf(size), .pen = start };
}

pub const GlyphIterator = struct {
    text: []const u8,
    s: f32,
    pen: f32,
    i: usize = 0,

    pub fn next(self: *GlyphIterator) ?GlyphPlacement {
        while (self.i < self.text.len) {
            const c = self.text[self.i];
            // Newlines are layout, not glyphs: the caller draws line by line.
            // Anything outside ASCII is one character, however many bytes it is.
            self.i += byteLen(self.text, self.i);
            if (c == '\n') continue;
            const g = glyphOf(c);
            const at = self.pen;
            self.pen += g.advance * self.s;
            return .{ .c = c, .x = at, .glyph = g };
        }
        return null;
    }
};

/// Splits `text` into lines that fit into `max_width`, breaking at spaces and
/// falling back to a hard break when a single word is too long (which is what
/// every UI has to do eventually, and doing it here keeps widgets honest).
///
/// Returns the number of lines written; the caller provides `out` (the frame
/// arena is the intended owner, so a frame costs no system allocation).
/// `Lines` borrows from `text`, so nothing is copied.
pub const Line = struct { start: usize, len: usize };

pub fn wrap(text: []const u8, size: f32, max_width: f32, out: []Line) []Line {
    const s = scaleOf(size);
    var n: usize = 0;

    // Width of `text[from..to]` at this scale.
    const widthOf = struct {
        fn f(t: []const u8, sc: f32, from: usize, to: usize) f32 {
            var w: f32 = 0;
            var i = from;
            while (i < to) : (i += byteLen(t, i)) w += advance(t[i], sc);
            return w;
        }
    }.f;

    // Last space in `text[from..to]`, if any.
    const lastSpace = struct {
        fn f(t: []const u8, from: usize, to: usize) ?usize {
            var i = to;
            while (i > from) {
                i -= 1;
                if (t[i] == ' ') return i;
            }
            return null;
        }
    }.f;

    var line_start: usize = 0;
    var i: usize = 0;
    var width: f32 = 0;
    var space: ?usize = null;

    while (i < text.len) : (i += 1) {
        const c = text[i];
        if (c == '\n') {
            if (n < out.len) out[n] = .{ .start = line_start, .len = i - line_start };
            n += 1;
            line_start = i + 1;
            width = 0;
            space = null;
            continue;
        }
        width += advance(c, s);
        if (c == ' ') space = i;
        if (width <= max_width) continue;

        // `text[line_start..i]` is the longest prefix that fits. Prefer to end
        // it at the last space; if the line has no usable space, break the word.
        var break_at: usize = i;
        if (space) |sp| {
            if (sp > line_start) break_at = sp;
        }
        if (n < out.len) out[n] = .{ .start = line_start, .len = break_at - line_start };
        n += 1;
        line_start = if (break_at == i) i else break_at + 1;
        // Re-measure what is already on the new line: exact, and a line is
        // short, so the second walk costs nothing that matters.
        width = widthOf(text, s, line_start, i + 1);
        space = lastSpace(text, line_start, i + 1);
    }

    if (line_start < text.len or n == 0) {
        if (n < out.len) out[n] = .{ .start = line_start, .len = text.len - line_start };
        n += 1;
    }
    return out[0..@min(n, out.len)];
}

/// An upper bound on the lines `wrap` can produce, so a caller can size its
/// buffer without guessing: one per character is always enough.
pub fn maxLines(text: []const u8) usize {
    return text.len + 1;
}

/// Coverage of one glyph pixel, as a byte. Out-of-range reads are transparent,
/// which is what a bilinear sample at the edge of a glyph needs.
pub fn coverage(g: data.Glyph, x: i32, y: i32) u8 {
    if (x < 0 or y < 0 or x >= g.w or y >= g.h) return 0;
    return data.alpha[g.offset + @as(usize, @intCast(y)) * g.w + @as(usize, @intCast(x))];
}

// Two structural invariants of the generated table. Both are properties of the
// data, not of any drawing code — and both fail loudly if `tools/gen_font.py`
// ever stores a padded bitmap or reorders the pool, which is exactly the bug
// that made every glyph tear diagonally once.

test "the glyph pool is packed in table order" {
    var expected: u32 = 0;
    for (data.glyphs) |g| {
        try std.testing.expectEqual(expected, g.offset);
        expected += @as(u32, g.w) * @as(u32, g.h);
        // A glyph with no ink has no bytes at all.
        if (g.w == 0 or g.h == 0) try std.testing.expectEqual(@as(u32, 0), @as(u32, g.w) * @as(u32, g.h));
    }
    try std.testing.expectEqual(@as(usize, expected), data.alpha.len);
}

test "every ink box is tight" {
    // The generator takes the box from the drawn pixels, so the ink has to touch
    // all four sides. A stride error shows up here immediately: an unpacked row
    // leaves whole edges of the box empty.
    for (data.glyphs) |g| {
        if (g.w == 0 or g.h == 0) continue;
        const right: i32 = @as(i32, @intCast(g.w)) - 1;
        const bottom: i32 = @as(i32, @intCast(g.h)) - 1;
        var top_ink = false;
        var bottom_ink = false;
        var left_ink = false;
        var right_ink = false;
        for (0..g.w) |x| {
            top_ink = top_ink or coverage(g, @intCast(x), 0) > 0;
            bottom_ink = bottom_ink or coverage(g, @intCast(x), bottom) > 0;
        }
        for (0..g.h) |y| {
            left_ink = left_ink or coverage(g, 0, @intCast(y)) > 0;
            right_ink = right_ink or coverage(g, right, @intCast(y)) > 0;
        }
        try std.testing.expect(top_ink and bottom_ink and left_ink and right_ink);
    }
}

test "a glyph looks like itself" {
    // The bytes could be in the pool in the right order and still be read wrong:
    // these three shapes are the cheapest way to see that a row of coverage is a
    // row of the glyph.

    // "o" is a ring: the middle is empty and the row through it has ink on both
    // sides of the hole.
    const o = glyphOf('o');
    const oy: i32 = @intCast(o.h / 2);
    const ox: i32 = @intCast(o.w / 2);
    try std.testing.expect(coverage(o, ox, oy) < 64);
    var left_ink = false;
    var right_ink = false;
    for (0..@as(usize, @intCast(ox))) |x| {
        if (coverage(o, @intCast(x), oy) > 0) left_ink = true;
    }
    for (@as(usize, @intCast(ox + 1))..o.w) |x| {
        if (coverage(o, @intCast(x), oy) > 0) right_ink = true;
    }
    try std.testing.expect(left_ink and right_ink);

    // "l" is a single vertical stroke: one run of ink per row.
    const l = glyphOf('l');
    for (0..@as(usize, l.h)) |y| {
        var runs: usize = 0;
        var prev = false;
        for (0..@as(usize, l.w)) |x| {
            const ink = coverage(l, @intCast(x), @intCast(y)) > 0;
            if (ink and !prev) runs += 1;
            prev = ink;
        }
        try std.testing.expectEqual(@as(usize, 1), runs);
    }

    // "T" starts with a full-width bar.
    const t = glyphOf('T');
    var bar: usize = 0;
    for (0..@as(usize, t.w)) |x| {
        if (coverage(t, @intCast(x), 0) > 0) bar += 1;
    }
    try std.testing.expectEqual(@as(usize, t.w), bar);
}

test "metrics of a known string" {
    // The master font is 14 px; advances come straight from the generated table.
    const one = measure(" ", 14);
    try std.testing.expectApproxEqAbs(@as(f32, 3.0), one.width, 1e-6);

    const hello = measure("Hello", 14);
    try std.testing.expect(hello.width > 20 and hello.width < 40);
    try std.testing.expectApproxEqAbs(@as(f32, 18.0), hello.height, 1e-6);
    try std.testing.expectApproxEqAbs(@as(f32, 14.0), hello.ascent, 1e-6);
    try std.testing.expectApproxEqAbs(@as(f32, 4.0), hello.descent, 1e-6);

    // Scaling is linear in the size.
    const big = measure("Hello", 28);
    try std.testing.expectApproxEqAbs(hello.width * 2, big.width, 1e-4);
    try std.testing.expectApproxEqAbs(hello.height * 2, big.height, 1e-4);

    // Empty text still occupies a line box.
    try std.testing.expectEqual(@as(f32, 0), measure("", 14).width);
    try std.testing.expectEqual(@as(f32, 18), measure("", 14).height);
}

test "a multi-byte character is one replacement glyph, not one per byte" {
    // "—" is three bytes; a host that hands the library UTF-8 must not see three
    // question marks.
    const dash = "\u{2014}";
    try std.testing.expectEqual(@as(usize, 3), dash.len);
    try std.testing.expectEqual(@as(usize, 3), byteLen(dash, 0));
    const one = measure("?", 14).width;
    try std.testing.expectApproxEqAbs(one, measure(dash, 14).width, 1e-6);
    try std.testing.expectApproxEqAbs(one * 2, measure(dash ++ dash, 14).width, 1e-6);

    var it = layout(dash, 14, 0);
    const g = it.next() orelse return error.TestUnexpectedResult;
    try std.testing.expectEqual(@as(u8, 0xe2), g.c);
    try std.testing.expect(it.next() == null);

    // A newline contributes nothing to a line's width — the caller lays out
    // lines, so it must not see phantom ink.
    try std.testing.expectApproxEqAbs(0, measure("\n\n", 14).width, 1e-6);
}

test "unknown bytes fall back to a printable glyph" {
    const q = glyphOf('?');
    try std.testing.expectEqual(q.advance, glyphOf(0).advance);
    try std.testing.expectEqual(q.advance, glyphOf(200).advance);
    try std.testing.expectEqual(q.w, glyphOf('\n').w);
}

test "layout places glyphs by advance" {
    var it = layout("ab", 14, 10);
    const a = it.next().?;
    const b = it.next().?;
    try std.testing.expectEqual(@as(u8, 'a'), a.c);
    try std.testing.expectApproxEqAbs(@as(f32, 10.0), a.x, 1e-6);
    try std.testing.expectApproxEqAbs(@as(f32, 10.0 + a.glyph.advance), b.x, 1e-6);
    try std.testing.expect(it.next() == null);
}

test "wrapping breaks at spaces and only overflows for a single long word" {
    var buf: [64]Line = undefined;
    const text = "the quick brown fox jumps over the lazy dog";
    const width = measure("the quick", 14).width + 1;
    const lines = wrap(text, 14, width, &buf);
    try std.testing.expect(lines.len >= 4);

    // Every line fits, except a line that is a single word longer than the box.
    for (lines) |line| {
        const piece = text[line.start .. line.start + line.len];
        if (piece.len == 0) continue;
        const w = measure(piece, 14).width;
        const has_space = std.mem.indexOfScalar(u8, piece, ' ') != null;
        if (has_space) try std.testing.expect(w <= width + 1e-3);
    }
    // No text is lost.
    var total: usize = 0;
    for (lines) |line| total += line.len;
    try std.testing.expect(total >= text.len - lines.len);

    // Explicit newlines always break.
    const two = wrap("a\nb", 14, 1000, &buf);
    try std.testing.expectEqual(@as(usize, 2), two.len);
    try std.testing.expectEqual(@as(usize, 1), two[0].len);
    try std.testing.expectEqual(@as(usize, 1), two[1].len);

    // A word wider than the box is broken, not dropped, and every piece fits
    // (or is a single glyph, which cannot be broken further).
    const long_text = "supercalifragilistic";
    const long = wrap(long_text, 14, 20, &buf);
    try std.testing.expect(long.len >= 2);
    var rebuilt: usize = 0;
    for (long) |line| {
        const piece = long_text[line.start .. line.start + line.len];
        rebuilt += piece.len;
        if (piece.len > 1) try std.testing.expect(measure(piece, 14).width <= 20 + 1e-3);
    }
    try std.testing.expectEqual(long_text.len, rebuilt);

    // The empty string still reports one (empty) line, so a caller can draw a
    // caret there.
    const empty = wrap("", 14, 100, &buf);
    try std.testing.expectEqual(@as(usize, 1), empty.len);
    try std.testing.expectEqual(@as(usize, 0), empty[0].len);
}

test "coverage reads are bounded" {
    const g = glyphOf('A');
    try std.testing.expect(g.h > 0);
    try std.testing.expectEqual(@as(u8, 0), coverage(g, -1, 0));
    try std.testing.expectEqual(@as(u8, 0), coverage(g, 0, -1));
    try std.testing.expectEqual(@as(u8, 0), coverage(g, @intCast(g.w), 0));
    var ink: usize = 0;
    for (0..g.h) |y| {
        for (0..g.w) |x| {
            if (coverage(g, @intCast(x), @intCast(y)) > 128) ink += 1;
        }
    }
    try std.testing.expect(ink > 10); // 'A' has some solid pixels
}
